style.css:
@-moz-document domain("deltamath.com") {
/* Background color */
    body {
        background-color: #2a1a3d !important;
        color: #f0f0f0 !important;
    }

    /* Links */
    a, a:visited {
        color: #bb66cc !important;
    }
    a:hover {
        color: #da66ff !important;
    }

    /* Headers */
    h1, h2, h3, h4, h5, h6 {
        color: #d1a0d7 !important;
    }

    /* Input fields */
    input, textarea, select {
        background-color: #3a2a5d !important;
        color: #f0f0f0 !important;
        border: 1px solid #5a3a88 !important;
    }

    /* Buttons */
    button {
        background-color: #4b2b7f !important;
        color: #fff !important;
        border: none;
    }
    button:hover {
        background-color: #6a3bbf !important;
    }

    /* Navbar */
    .navbar, .header {
        background-color: #1f0e3e !important;
        color: #e0b8e0 !important;
    }

    /* Table rows */
    table, th, td {
        border: 1px solid #4a2c74 !important;
    }
    th {
        background-color: #3b1d59 !important;
    }
    tr:nth-child(even) {
        background-color: #2e1536 !important;
    }
}
